with base as (select *, initcap(trim(dept_name)) dept_name_title from departments where budget > 1967000 and budget < 2806000 and location <> 'Singapore'), departments_stats as (select dept_name, max(budget) max_budget, round(avg(budget), 2) avg_budget from base group by dept_name) select * from departments_stats where avg_budget >= 42 order by max_budget, avg_budget desc, dept_name limit 50
